                ['title' => 'Convert and read the unit', 'description' => 'Select Convert Unit and use the destination symbol shown beside the result.'],
                ['title' => 'Apply suitable rounding', 'description' => 'Keep enough precision for the task and follow the destination form, recipe or specification’s rounding requirement.'],
