            'formula_variables' => [
                ['symbol' => 'Source value', 'meaning' => 'The measurement entered in the selected source unit.'],
                ['symbol' => 'Conversion factor', 'meaning' => 'The fixed multiplier relating compatible length, weight or volume units.'],
